// Presentation-only gate. This is not authentication or a real VPN connection.
window.demoSession=null;
(()=>{
const shell=document.querySelector('.app');const root=document.createElement('section');root.id='login-screen';document.body.prepend(root);let stage='identity',attempt=0,busy=false;
const profiles=[{name:'Mumbai · Dedicated 01',region:'India',ip:'192.0.2.10'},{name:'Singapore · Dedicated 03',region:'Singapore',ip:'198.51.100.20'},{name:'London · Dedicated 04',region:'United Kingdom',ip:'203.0.113.30'}];
let chosen=0;
const header=document.querySelector('header');const chip=document.createElement('button');chip.id='session-network';chip.className='session-network';chip.title='Review the simulated login network';chip.onclick=()=>lock('network');header.insertBefore(chip,header.querySelector('.demo-chip'));const logout=document.createElement('button');logout.className='logout-button';logout.textContent='Sign out';logout.onclick=()=>lock('identity');header.append(logout);
function lock(next){attempt++;busy=false;window.demoSession=null;stage=next;shell.inert=true;shell.hidden=true;document.body.classList.add('login-required');document.querySelector('#dialog').close();root.hidden=false;draw();window.scrollTo(0,0)}
function draw(){root.innerHTML=`<div class="login-story"><a href="#" class="brand"><span class="logo">aw</span><span>Ad Workspace<small>BY SRS LOGICS</small></span></a><div class="login-message"><div class="eyebrow">ADVERTISING OPERATIONS</div><h1>Ad Workspace</h1><p>Campaign management and reporting for your team.</p><div class="login-steps"><span class="${stage==='identity'?'current':'done'}">01 &nbsp; Sign in</span><span class="${stage==='network'?'current':''}">02 &nbsp; Network check</span><span>03 &nbsp; Workspace</span></div></div><div class="login-story-foot">SRS Logics · Advertising management</div></div><div class="login-form-side"><div class="login-card"><span class="demo-chip">INTERACTIVE DEMO</span><h2>${stage==='identity'?'Sign in':'Verify network access'}</h2><p class="login-intro">${stage==='identity'?'Use the sample credentials to explore the workspace.':'Choose a login network profile and run the connection simulation.'}</p>${stage==='identity'?`<form id="login-form"><label>Demo email<input name="email" type="email" value="demo@example.com" autocomplete="off" required></label><label>Demo password<div class="password-wrap"><input name="password" type="password" value="DemoAccess!" autocomplete="off" required><button type="button" id="show-password" aria-label="Show password">Show</button></div></label><div class="demo-credentials"><strong>Sample credentials</strong><span>demo@example.com &nbsp; / &nbsp; DemoAccess!</span><small>Use these demo values only. Do not enter a real password.</small></div><p id="login-error" role="alert"></p><button class="primary login-submit" type="submit">Continue to network check </button></form>`:`<form id="network-login-form"><label>Login network profile<select name="profile" id="login-profile">${profiles.map((p,i)=>`<option value="${i}" ${chosen===i?'selected':''}>${p.name}</option>`).join('')}</select></label><div class="route-preview"><span>Connection type<strong>Dedicated gateway · simulated</strong></span><span>Example outbound IP<strong id="example-ip">${profiles[chosen].ip}</strong></span></div><label class="failure-option"><input type="checkbox" name="fail"> Test an unavailable connection</label><div class="connection-progress" id="connection-progress" role="status" aria-live="polite">Network check required before demo access.</div><button class="primary login-submit" type="submit">Simulate VPN connection & enter </button><button type="button" id="back-login" class="login-back">← Back to sign in</button></form>`}<div class="login-disclosure"><b>Demo only — no real authentication or VPN.</b><p>No connection is established and your device IP stays unchanged. Production access requires server-side authentication and a verified network gateway.</p></div></div><div class="login-foot">Web application & PWA · SRS Logics</div></div>`;
if(stage==='identity'){document.querySelector('#show-password').onclick=e=>{let p=root.querySelector('[name=password]'),show=p.type==='password';p.type=show?'text':'password';e.target.textContent=show?'Hide':'Show';e.target.setAttribute('aria-label',show?'Hide password':'Show password')};document.querySelector('#login-form').onsubmit=e=>{e.preventDefault();const f=e.target;if(f.email.value.trim()!=='demo@example.com'||f.password.value!=='DemoAccess!'){document.querySelector('#login-error').textContent='Use the sample email and password shown above.';return}f.password.value='';stage='network';draw();root.querySelector('select').focus()}}else{root.querySelector('#back-login').onclick=()=>lock('identity');root.querySelector('#login-profile').onchange=e=>{chosen=Number(e.target.value);document.querySelector('#example-ip').textContent=profiles[chosen].ip};root.querySelector('#network-login-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const run=++attempt;const f=e.target;const fail=f.fail.checked;const p=profiles[chosen];f.querySelectorAll('button,input,select').forEach(x=>x.disabled=true);const status=root.querySelector('#connection-progress');const sleep=()=>new Promise(r=>setTimeout(r,550));for(const message of ['Checking demo profile…','Simulating gateway connection…','Validating sample route…']){status.classList.remove('failed');status.textContent=message;await sleep();if(run!==attempt)return}busy=false;if(fail){status.textContent='Sample connection failed. Workspace access remains blocked. Uncheck the test option and retry.';status.classList.add('failed');f.querySelectorAll('button,input,select').forEach(x=>x.disabled=false);return}window.demoSession={profile:p.name,ip:p.ip,simulated:true};chip.textContent='◈ '+p.region+' · Demo VPN';root.hidden=true;shell.hidden=false;shell.inert=false;document.body.classList.remove('login-required');document.querySelector('#main').focus();window.scrollTo(0,0)}}}
lock('identity');
window.addEventListener('pagehide',()=>{attempt++;window.demoSession=null});
})();
